  "brown|maroon": 4,
  "brown|mustard": 5,
  "brown|rust": 4,
  "brown|orange": 4,
  "brown|teal": 4,
  "brown|forest": 4,
  "camel|rust": 4,
  "camel|terracotta": 4,
  "rust|tan": 4,
  "red|white": 4,
  "teal|white": 4,
