for y in 0..<h { for x in 0..<w {
  guard let c = rep.colorAt(x: x, y: y) else { continue }
  // anything meaningfully darker than the white canvas is artwork
  if c.alphaComponent > 0.1 && (c.redComponent < 0.93 || c.greenComponent < 0.93 || c.blueComponent < 0.93) {
    if x < minX { minX = x }; if x > maxX { maxX = x }
    if y < minY { minY = y }; if y > maxY { maxY = y }
  }
}}
guard maxX > 0 else { print("no artwork found"); exit(1) }
let bw = maxX - minX + 1, bh = maxY - minY + 1
