// Target: the artwork at 2x its 168x34 aspect, with a little breathing room.
let W = 336, H = 68
let scale = min(Double(W) / Double(bw), Double(H) / Double(bh))
let dw = Int(Double(bw) * scale), dh = Int(Double(bh) * scale)
